const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const db = new sqlite3.Database(path.join(__dirname, 'alerting.db'));

// Wrapper to mimic better-sqlite3 API with promises
db.prepare = (sql) => {
  return {
    run: (...params) => new Promise((resolve, reject) => {
      db.run(sql, params, function(err) {
        if (err) reject(err);
        else resolve({ lastID: this.lastID, changes: this.changes });
      });
    }),
    get: (...params) => new Promise((resolve, reject) => {
      db.get(sql, params, (err, row) => {
        if (err) reject(err);
        else resolve(row);
      });
    }),
    all: (...params) => new Promise((resolve, reject) => {
      db.all(sql, params, (err, rows) => {
        if (err) reject(err);
        else resolve(rows);
      });
    })
  };
};

const originalExec = db.exec.bind(db);
db.exec = (sql) => new Promise((resolve, reject) => {
  originalExec(sql, (err) => {
    if (err) reject(err);
    else resolve();
  });
});

// Initialize database
(async () => {
  try {
    await db.exec(`
      CREATE TABLE IF NOT EXISTS rules (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        severity_threshold TEXT NOT NULL,
        service_name TEXT DEFAULT '',
        channel TEXT NOT NULL DEFAULT 'slack',
        created_at TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS alerts (
        id TEXT PRIMARY KEY,
        incident_id TEXT NOT NULL,
        rule_id TEXT NOT NULL,
        rule_name TEXT NOT NULL,
        channel TEXT NOT NULL,
        triggered_at TEXT NOT NULL
      );
    `);

    // Insérer des règles par défaut si la table est vide
    const count = await db.prepare('SELECT COUNT(*) as c FROM rules').get();
    if (count.c === 0) {
      const { v4: uuidv4 } = require('uuid');
      const now = new Date().toISOString();
      await db.prepare(`INSERT INTO rules VALUES (?, ?, ?, ?, ?, ?)`)
        .run(uuidv4(), 'Alerte CRITICAL (tous services)', 'CRITICAL', '', 'slack', now);
      await db.prepare(`INSERT INTO rules VALUES (?, ?, ?, ?, ?, ?)`)
        .run(uuidv4(), 'Alerte HIGH par email', 'HIGH', '', 'email', now);
      console.log('[Alerting] Règles par défaut créées');
    }
  } catch (err) {
    console.error('[Alerting] Erreur init DB:', err);
  }
})();

module.exports = db;
